var showHideEuElements = function showHideEuElements(isEu) {
  document.querySelectorAll('.eu-hide').forEach(function (el) {
    if (!isEu && el.classList.contains('invisible')) {
      // Keep original display type if invisible was specified.
      el.classList.remove('invisible');
    } else {
      // Default to setting display to block.
      el.setAttribute('display', (!isEu ? 'block' : 'none') + " !important");
    }
  });
  document.querySelectorAll('.eu-show', '.eu-only').forEach(function (el) {
    if (isEu && el.classList.contains('invisible')) {
      el.classList.remove('invisible');
    } else {
      el.setAttribute('display', (isEu ? 'block' : 'none') + " !important");
    }
  });
};
